//! An allowlist-gated token where transfers are restricted to addresses
//! approved by an admin.
//!
//! Generated by [soroban-forge](https://github.com/soroban-forge-labs/soroban-forge).

#![no_std]

use soroban_sdk::{
    contract, contracterror, contractevent, contractimpl, contracttype, panic_with_error, Address,
    Env, String,
};

const DAY_IN_LEDGERS: u32 = 17280;
const BALANCE_BUMP_AMOUNT: u32 = 30 * DAY_IN_LEDGERS;
const BALANCE_LIFETIME_THRESHOLD: u32 = BALANCE_BUMP_AMOUNT - DAY_IN_LEDGERS;
const ALLOWANCE_BUMP_AMOUNT: u32 = 30 * DAY_IN_LEDGERS;
const ALLOWANCE_LIFETIME_THRESHOLD: u32 = ALLOWANCE_BUMP_AMOUNT - DAY_IN_LEDGERS;
/// Instance entry (admin, metadata, total supply) lives 30 days and is bumped
/// whenever it drops below 29 days, so it is never archived while in use.
pub const INSTANCE_TTL: u32 = 30 * DAY_IN_LEDGERS;
pub const INSTANCE_TTL_THRESHOLD: u32 = INSTANCE_TTL - DAY_IN_LEDGERS;

#[contracterror]
#[derive(Copy, Clone, Debug, Eq, PartialEq)]
#[repr(u32)]
pub enum Error {
    /// Caller is not the admin.
    NotAdmin = 1,
    /// Address is not on the allowlist.
    NotAllowed = 2,
    /// Amount must be positive.
    InvalidAmount = 3,
    /// Insufficient balance.
    InsufficientBalance = 4,
    /// Arithmetic overflow.
    Overflow = 5,
    /// Insufficient allowance.
    InsufficientAllowance = 6,
    /// No admin handover is pending.
    NoPendingAdmin = 7,
}

#[contracttype]
#[derive(Clone)]
pub enum DataKey {
    Admin,
    Name,
    Symbol,
    Decimals,
    Allowed(Address),
    /// Address offered the admin role, awaiting `accept_admin`.
    PendingAdmin,
    Balance(Address),
    Allowance(Address, Address),
    TotalSupply,
}

/// `admin` offered the admin role to `new_admin`.
#[contractevent]
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct AdminProposed {
    #[topic]
    pub admin: Address,
    pub new_admin: Address,
}

/// `new_admin` accepted the handover and replaced `old_admin`.
#[contractevent]
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct AdminTransferred {
    #[topic]
    pub old_admin: Address,
    pub new_admin: Address,
}

/// The pending handover to `new_admin` was cancelled by `admin`.
#[contractevent]
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct AdminProposalCancelled {
    #[topic]
    pub admin: Address,
    pub new_admin: Address,
}

